Ltac slia_atom := first [ exact I | assumption | match goal with K : chunk_disj _ _ _ _ |- _ => exact K end
                        | lazymatch goal with |- not _ => intros ?; repeat match goal with K : _ /\ _ |- _ => destruct K end;
                                                          match goal with K : not _ |- _ => apply K; split; lia_t1 end end
                        | dj_lia ].
Ltac slia_conj := first [ exact I | lazymatch goal with |- _ /\ _ => split; [slia_atom| slia_conj] end | slia_atom ].
Ltac slia ::= slia_conj.

(* [comment removed for export] *)
Ltac wseed H l h :=
  let go A2 s2 := (let W := fresh "WS" in assert (W : hideL (A2 + s2 <= l \/ h <= A2)); [unfold hideL|]) in
  lazymatch type of H with
  | rw_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  | ro_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  end.

Lemma acc_transport_lowhi : forall W m m' a n,
  accessible m a n -> munch W m m' -> Forall (fun iv : Z * Z => snd iv <= ALOWSH_LO \/ AHI_LO <= fst iv) W ->
  0 <= a -> a + n <= AAPP_HI -> accessible m' a n.
Proof.
  intros W m m' a n AC MU FW A0 AH. eapply accessible_transport; [exact AC| exact MU|].
  intros x Hx. pose proof (sh_ge_lowsh x ltac:(lia)) as L. pose proof (sh_below_app x ltac:(lia)) as U.
  clear - FW L U. induction W as [|[l h] W IH]; [exact I|]. cbn [outside fst snd]. split; [| exact (IH (Forall_inv_tail FW))].
  pose proof (Forall_inv FW) as K. cbn [fst snd] in K. lia.
Qed.

