Definition rs_W2 (lo : Z) (sp : word) (fb ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -104); (fb + 8, fb + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64);
   (ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 32); (fp, fp + 1)]%Z.

Definition rs_after_put_post (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (LF : list fframe) (lo shi spa ff fp E bs fb P tot : Z) (FBC : list cell)
    (hw : word) (optc : list cell) (j56 : list byte) (ectc : list cell) (j120 : list byte) (ob eb : Z) (mw80 : cell) (gap : list cell)
    (s6x : word) (used : Z) (E1 : ecv) : machine_state -> Prop :=
  fun ms' => exists m',
          munch (rs_W2 lo sp fb ff fp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
       /\ rw_cells bsegs m' fb FBC
       /\ rw_cells bsegs m' E (ErrCodeCells E1)
       /\ AHttpCat m' true /\ AXStatics2 m' /\ ACONST m' /\ stack0 m' lo shi /\ accessible m' E 24
       /\ (   (is_needmore E1 = false /\ as_RFS H LF m' /\ stk bsegs m' lo (bv_unsigned sp)
               /\ exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6,
                    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0v s1v (wz tot) a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6)
                             F (ret_pc ra) fc None m' (seg_rom bsegs))
           \/ (is_needmore E1 = true /\ as_RFS H ((2, ff, fp) :: LF) m' /\ stk bsegs m' lo spa
               /\ rs_frame m' sp spa ff E bs P fb mw80 (ErrCodeCells (EC_http 3)) gap
               /\ rw_cells bsegs m' (bv_unsigned sp + -104) (rs_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)
               /\ rs_fake m' ff fp hw optc j56 ectc j120 ob eb
               /\ exists rax' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6',
                    ms' = rs_ms RS_DOREAD rax' sp spa gp tp t0' t1' t2' E a0' a1' a2' a3' a4' a5' a6' a7' tot fb ff (wz used) s6x t3' t4' t5' t6' F fc m')).
