    (F : bvmap 5 word) fc (m0 m : mem) (LF : list fframe) (lo shi spa ff fp E bs fb P tot used ob eb : Z) (FB : fbv) (E1 : ecv) (g : bool)
    (hw : word) (mw80 : cell) (tmp gap optc ectc : list cell) (j56 j120 : list byte),
  as_RFS H LF m0 ->
  rs_frame m sp spa ff E bs P fb mw80 tmp gap ->
  rw_cells bsegs m (bv_unsigned sp + -104) (rs_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rs_fake m ff fp hw optc j56 ectc j120 ob eb ->
  as_RFS H ((2, ff, fp) :: LF) m -> fresh_frame H LF 2 ff fp ->
  rw_cells bsegs m fb (FlatBufCells FB) -> fb mod 8 = 0 -> aapp fb 48 -> fsobj H LF fb 48 -> accessible m fb 48 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_last FB <= fb_end FB -> fb_end FB <= aceil ->
  (0 < fb_size FB -> 0 < fb_begin FB) -> 0 <= used <= fb_size FB ->
  rw_cells bsegs m E (ErrCodeCells E1) -> ec_ok E1 -> (E1 = EC_clear \/ http_fail E1) ->
  aapp E 24 -> fsobj H LF E 24 -> accessible m E 24 -> E mod 8 = 0 -> (fb + 48 <= E \/ E + 24 <= fb) ->
  AHttpCat m g -> AXStatics2 m ->
  stk bsegs m lo spa -> lo + 272 + AASSIGN_STACK <= bv_unsigned sp -> aceil <= lo ->
  0 <= bs < 2^64 -> 0 <= P < 2^64 -> 0 <= tot -> tot + used < 2^63 -> bv_unsigned ra mod 2 = 0 -> bv_unsigned sp mod 16 = 0 ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (rs_after_put_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc m LF lo shi spa ff fp E bs fb P (tot + used)
               (FlatBufCells (fb_consume FB used)) hw optc j56 ectc j120 ob eb mw80 gap s6x used E1)
    (rs_ms RS_PUTRET rax sp spa gp tp t0 t1 t2 E (wz used) a1 a2 a3 a4 a5 a6 a7 tot fb ff s5x s6x t3 t4 t5 t6 F fc m).
Proof.
